const mission = ($json.mission || "").toLowerCase();
const context = JSON.stringify($json.context || {}).toLowerCase();
const data = JSON.stringify($json.data || {}).toLowerCase();
const text = [mission, context, data].join(" ");

function hasAny(words){ return words.some(w => text.includes(w)); }

const flags = {
  seo: hasAny(["seo","intent","mot-cl","serp","maillage","cocon","rank","gsc","ctr","schema"]),
  wp: hasAny(["wordpress","wp","plugin","theme","fse","performance","cache","hosting","security","o2switch","lws"]),
  automation: hasAny(["automation","n8n","webhook","fluentcrm","tags","sequence","segmentation","scoring","trigger"]),
  monetization: hasAny(["prix","offre","pack","upsell","retainer","affiliation","cta","conversion","revenue"]) 
};
if(!flags.seo && !flags.wp && !flags.automation && !flags.monetization){ flags.seo=true; flags.monetization=true; }
return [{ json: { ...$json, routing: flags, routing_summary: Object.entries(flags).filter(([,v])=>v).map(([k])=>k).join(", ") } }];
